args.sql:
ALTER TABLE transactions
ADD COLUMN adjusted_rate NUMERIC;

UPDATE transactions t
SET adjusted_rate = m.esccomprate
FROM markets m
WHERE t.mktref = m.mktregistry;

CREATE INDEX idx_anomaly_detection ON transactions (adjusted_rate);

